<div class="modal fade" id="pharmacyOrderCreateModal" tabindex="-1" role="dialog" aria-labelledby="pharmacyOrderCreateTitle" aria-hidden="true"><div class="modal-dialog modal-dialog-centered" role="document"><form class="modal-content" id="pharmacyOrderCreateForm" method="post" action="<?= base_url('pharmacy/orders/create') ?>"><div class="modal-header"><h2 class="modal-title h5" id="pharmacyOrderCreateTitle">Create medicine order</h2><button type="button" class="close" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button></div><div class="modal-body"><?= csrf_field() ?><label for="orderPrescription">Approved prescription</label><select class="form-control" name="prescription_id" id="orderPrescription" required><option value="">Select an approved prescription</option><?php foreach (($approvedPrescriptions ?? []) as $prescription): ?><option value="<?= (int) $prescription['id'] ?>"><?= esc(($prescription['prescription_number'] ?? 'Prescription') . ' — ' . ($prescription['registration_number'] ?? 'Patient') . ' — ' . (($prescription['prescription_date'] ?? '') ?: 'Date unavailable')) ?></option><?php endforeach; ?></select><div class="validation-error" id="prescription_idErr"></div><p class="small text-muted mt-2 mb-0">Stock is allocated server-side using active, unexpired batches and FEFO ordering.</p></div><div class="modal-footer"><button class="btn btn-light" type="button" data-dismiss="modal">Close</button><button class="btn btn-primary" type="submit">Create order</button></div></form></div></div>
